import{_ as s,c as o,o as a,a2 as r}from"./chunks/framework.DkPtUiZm.js";const m=JSON.parse('{"title":"Lot Google Play — SIA UI Demo","description":"","frontmatter":{},"headers":[],"relativePath":"assets/google-play/README.md","filePath":"assets/google-play/README.md","lastUpdated":1795438092000}'),t={name:"assets/google-play/README.md"};function n(l,e,i,p,c,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="lot-google-play-—-sia-ui-demo" tabindex="-1">Lot Google Play — SIA UI Demo <a class="header-anchor" href="#lot-google-play-—-sia-ui-demo" aria-label="Permalink to &quot;Lot Google Play — SIA UI Demo&quot;">​</a></h1><p>Images françaises préparées le 22 novembre 2026 depuis l&#39;application Android 1.0.0, versionCode 1, installée sur un téléphone. L&#39;APK installé a la même empreinte SHA-256 que le build EAS preview identifié dans <code>manifest.json</code>.</p><h2 id="importer-dans-play-console" tabindex="-1">Importer dans Play Console <a class="header-anchor" href="#importer-dans-play-console" aria-label="Permalink to &quot;Importer dans Play Console&quot;">​</a></h2><ol><li><strong>Icône</strong> : <code>icone-512.png</code>.</li><li><strong>Image de présentation</strong> : <code>fr-FR/image-presentation-1024x500.png</code> pour la version sombre, ou <code>fr-FR/image-presentation-claire-1024x500.png</code> pour la claire.</li><li><strong>Visuels téléphone</strong> : importer dans l&#39;ordre les huit PNG de <code>fr-FR/carrousel-v2/</code>. Les téléphones et rubans se poursuivent dans les paires 01–02, 03–04, 05–06 et 07–08. Conserver cet ordre.</li><li>Reporter les textes alternatifs fournis dans <code>textes-alternatifs.md</code>.</li></ol><p>Le lot contient aussi douze captures simples alternatives, six par thème dans <code>fr-FR/telephone/</code>, et une sélection simple de huit dans <code>fr-FR/selection-8/</code>. Choisir au plus huit images pour un même type d&#39;appareil. <code>apercu-carrousel-v2.png</code> présente les compositions avec téléphones ; <code>apercu-captures.png</code> présente les alternatives simples. Ces planches servent à la revue ; les images de <code>fr-FR/</code> sont les exports destinés à la fiche.</p><h2 id="dimensions-et-sources" tabindex="-1">Dimensions et sources <a class="header-anchor" href="#dimensions-et-sources" aria-label="Permalink to &quot;Dimensions et sources&quot;">​</a></h2><ul><li>Icône : 512 × 512, PNG 32 bits à fond opaque, sans coins préarrondis.</li><li>Bannières : 1024 × 500, PNG RGB sans transparence.</li><li>Captures : 1080 × 1920, PNG RGB sans transparence, ratio 9:16.</li><li><code>sources/</code> : compositions SVG éditables et captures applicatives recadrées.</li><li><code>sources/carrousel-v2/</code> : panoramas imagegen originaux et normalisés, prompts.</li><li><code>manifest.json</code> : provenance, ordre, textes alternatifs et empreintes des PNG.</li></ul><p>Le carrousel avec téléphones a été généré avec l&#39;outil imagegen intégré, à partir des captures Android. Il s&#39;agit de compositions marketing : les écrans peuvent présenter des différences de détail liées à la génération. Les moitiés de chaque paire se réassemblent exactement en leur panorama normalisé.</p><p>Dans les captures simples, les barres système ont été retirées ; l&#39;interface conserve ses proportions et ses couleurs. Les textes et contrôles de l&#39;application n&#39;ont pas été retouchés. Les noms et adresses affichés sont des données de démonstration. Les images ne valent pas publication de la fiche dans Play Console.</p><p>Après un changement visible de l&#39;APK, renouveler les captures concernées et recréer la sélection, l&#39;aperçu et le ZIP. Les sources SVG peuvent être ouvertes dans un éditeur vectoriel prenant en charge les images PNG liées.</p><p>Voir <code>docs/guides/visuels-google-play.md</code> dans le dépôt pour la procédure et les <a href="https://support.google.com/googleplay/android-developer/answer/9866151?hl=fr" target="_blank" rel="noreferrer">consignes Google Play</a>.</p>',11)])])}const g=s(t,[["render",n]]);export{m as __pageData,g as default};
